-- -- runtime lookup --------------------------------------------------
-- ItemEnchantmentMgr keeps its group table in a file-scope static with no
-- accessor, so re-tiering an affix at runtime would mean editing core.
-- These two tables carry the answer instead; all the name matching is
-- done here, offline.
DROP TABLE IF EXISTS `alonecraft_random_affix`;
CREATE TABLE `alonecraft_random_affix` (
  `property` INT UNSIGNED NOT NULL PRIMARY KEY,
  `affix` SMALLINT UNSIGNED NOT NULL,
  KEY `idx_affix` (`affix`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
DROP TABLE IF EXISTS `alonecraft_random_tier`;
CREATE TABLE `alonecraft_random_tier` (
  `affix` SMALLINT UNSIGNED NOT NULL,
  `group_id` INT UNSIGNED NOT NULL,
  `property` INT UNSIGNED NOT NULL,
  PRIMARY KEY (`affix`, `group_id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;








































